"""Minimum Number of Days to Make m Bouquets — binary search on the day.

Waiting longer never removes a bloomed flower, so feasibility is monotonic.

Time: O(n log max(bloomDay))   Space: O(1)
"""
from typing import List


class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        if m * k > len(bloomDay):
            return -1

        def bouquets_by(day: int) -> int:
            made = run = 0
            for bloom in bloomDay:
                if bloom <= day:
                    run += 1
                    if run == k:
                        made += 1
                        run = 0
                else:
                    run = 0
            return made

        lo, hi = min(bloomDay), max(bloomDay)
        while lo < hi:
            mid = (lo + hi) // 2
            if bouquets_by(mid) >= m:
                hi = mid
            else:
                lo = mid + 1
        return lo
